"""Generate the master guide and inventories from current backend evidence."""
import json
from pathlib import Path
from app.services import analogue_v1_service as av
from app.services.geospatial_service import BACKEND_ROOT
from app.main import app

DOCS = BACKEND_ROOT.parent / "docs"


def build():
    paper = json.loads((DOCS / "paper/paper-data.json").read_text(encoding="utf-8"))
    registry = json.loads((BACKEND_ROOT / "data/manifests/acquisition-v1/source-registry.json").read_text(encoding="utf-8"))
    example = paper["example"]
    blocks = [{"type": "title", "text": "AlterEcho System and Research Guide"},
              {"type": "p", "text": "Team AlterEcho | Research prototype | 15 November 2026"},
              {"type": "p", "text": "AlterEcho compares exact Earth and planetary terrain windows using traceable elevation measurements. This guide explains the implemented software, its numerical method, reproducibility and limits. Only terrain supports a numerical analogue result; the application does not establish mission suitability or predictive accuracy."}]
    def section(title, text):
        blocks.extend([{"type": "h1", "text": title}, {"type": "p", "text": text}])
    def code(text):
        blocks.append({"type": "code", "text": text})
    section("1 Project purpose", "Shortlist Earth terrain for research and field-method discussions by comparing registered 10 km windows with specific Mars or lunar windows. A high terrain index indicates similarity of two distributions at the tested scale, not comprehensive similarity to a planet.")
    section("2 NASA challenge connection", "The repository identifies Team AlterEcho's NASA Space Apps 2026 challenge as identifying Earth locations analogous to permanent Moon-base locations and Mars. AlterEcho contributes a transparent terrain-comparison prototype. Participation does not imply NASA endorsement, validation or operational approval.")
    section("3 What AlterEcho does", "The atlas serves cached, versioned scientific artifacts. Python performs deterministic measurement, eligibility checks, comparison and ranking. Users can inspect raw measurements, source products, quality limitations, evidence coverage and scenario sensitivity, then export the same backend result used by the interface.")
    section("4 What AlterEcho cannot establish", "DEM similarity cannot establish geology, minerals, soil bearing strength, rock hazards, wheel-scale traversability, construction feasibility, life, habitability, resource abundance, landing safety, radiation safety, access or permits. Regional analogue literature is context or a future validation label, never a numerical input.")
    section("5 User workflow", "Choose Mars or Moon, then a processed reference and task profile. Select a comparable Earth candidate; inspect imagery and terrain at the same ground scale. Read the simple result, evidence coverage and limitations, then open full evidence for equations, distributions, tolerances and source details. Download JSON or open the printable report. The Moon currently offers distances only. Explore screens a new Earth AOI without enrolling it in the atlas.")
    section("6 System architecture", "A Next.js application calls the FastAPI backend. The backend reads the catalog, task configuration and small processed artifacts. Offline acquisition and processing scripts produce immutable source checksums and versioned measurements. A bounded Explore worker obtains approved Earthdata products only when necessary. Provider credentials remain on the server.")
    blocks.append({"type": "diagram", "text": "architecture", "nodes": ["Browser atlas", "FastAPI routes", "Python comparison", "Versioned artifacts", "Official products"]})
    section("7 Frontend architecture", "App Router pages cover Atlas, Explore, Method, Sources and Report. Typed API clients and keyed hooks load backend responses. Atlas components render candidate lists, synchronized image views, charts and evidence panels. The frontend does not calculate the scientific index. Semantic color tokens support Light, Dark and System; a pre-paint script applies saved preference, while reduced-motion rules suppress transitions.")
    section("8 Backend architecture", "app/main.py installs bounded-body and security-header middleware, CORS and safe exception handlers. Routers separate catalog, historical comparison, current v3 comparison, provenance and Explore. analogue_v1_service orchestrates the current method; analogue_math provides authoritative arithmetic. terrain_quantiles measures rasters. Historical endpoints remain explicitly versioned for reproducibility.")
    section("9 Processing pipeline", "Discover an exact official product, record its metadata, verify access and licence, acquire into ignored raw storage, hash and inspect it, then construct the registered metric window with a processing halo. Resample elevation before computing derivatives. Apply documented masks, compute feature-specific valid coverage and quantiles, and preserve output checksums. A serving request validates the current derived artifact against its checksum and manifest; raw multi-GB files are checked during release reproduction.")
    blocks.append({"type": "diagram", "text": "data-flow", "nodes": ["Product metadata", "Raw SHA256", "AOI and mask", "Metric grid and halo", "Quantiles and quality", "API and export"]})
    section("10 Dataset registry", "The source-registry-v1 JSON in backend/data/manifests/acquisition-v1 is the machine-readable release inventory. Its Pydantic model and JSON Schema require source roles, provenance fields, byte counts and checksums. Collection entries describe candidates; product entries audit exact local inputs. Null metadata means not established. Verified denotes recorded metadata and byte integrity, not independent scientific validation. The /api/v3/source-registry endpoint exposes this inventory.")
    section("11 Earth datasets", "SRTMGL1.003 is the primary Earth terrain product, a radar surface model whose postings are about 30 m. NASADEM and Copernicus GLO-30 are sensitivity products, not mixed cells in the primary score. WorldCover v200 supplies a built-up exclusion mask; it misses some industrial terrain. Sentinel-2 L2A is display-only. Existing Aqua MYD11A2.061 thermal measurements are retained as diagnostic context; a Terra MODIS replacement is unnecessary without a defined comparability benefit.")
    section("12 Mars datasets", "Jezero retains the existing USGS Mars 2020 CTX DEM. Gale, InSight, Gusev and Eberswalde retain official controlled CTX stereo DTMs and associated imagery. Their 20 m postings do not guarantee 20 m effective resolution; stereo noise and incomplete pixels matter. MOLA is a coarse context or alignment check. MEDA temperature has rover-point support and does not establish an AOI-wide thermal match. CRISM mineral processing remains unavailable.")
    section("13 Moon datasets", "The registered south-pole window uses a local metres-valued LOLA-derived DEM. Four 2 km reference translations produce a relative-elevation floor too large for the frozen tolerance, so no lunar index or ranking is issued. Track spacing, interpolation and polar projection limit interpretation. Illumination, permanently shadowed regions, alternate lunar DEMs, Diviner temperature and regolith/resource variables are not validated evidence families.")
    section("14 Registered AOIs", "Every row below has a local terrain input and a stored terrain-v5 artifact. Eligibility is conditional on the selected task and reference. The original Atacama window is excluded for industrial contamination; the lunar window is diagnostic. Holuhraun and McMurdo remain planned.")
    blocks.append({"type": "table", "caption": "Exact registered centres and nominal support", "header": ["Site", "Longitude", "Latitude", "Width m", "Role"], "rows": [[s["site_id"], str(s["center"][0]), str(s["center"][1]), str(s["width_m"]), "terrain eligible" if s["scoring_eligible"] else "diagnostic or excluded"] for s in registry["sites"]]})
    section("15 Imagery and evidence roles", "Scored evidence, diagnostic evidence, quality masks, display imagery, research context and planned evidence have distinct roles. Sentinel true colour, CTX orthoimages and globe textures never enter terrain arithmetic. Source imagery is not recolored by the theme. Imagery timestamps come from metadata; latest context is archived acquisition, not a live measurement. Scene cloud coverage differs from AOI cloud/shadow/snow and footprint coverage.")
    section("16 Native resolution and analysis grid", "Native pixel spacing is retained separately from the shared 60 m analysis grid. A nominal 10 km square requires ceil(10000/60) = 167 cells, hence 10020 m actual raster support. The 120 m and 240 m grids are scale scenarios. Earth uses local UTM, Mars a product-appropriate metric planetary projection, and the lunar pole a polar projection. Relative elevation subtracts each window median; absolute heights with unlike vertical references are not compared.")
    section("17 Data quality gates", "Both sides must measure the same construct in compatible units, on the same grid and support with valid coverage at least " + str(av.MIN_COVERAGE) + ". Required scored features must have finite ordered 500-quantile distributions. Source/body/AOI identity, official source URL, source checksum chain and derived checksum must agree. Future processing dates, fixture inputs and invalid coordinates are rejected. Missing data reduce coverage and never become zero similarity. Unknown effective resolution and product-label metadata remain review limitations.")
    section("18 Implemented equations", "The production calculation approximates Wasserstein distance using 500 midpoint samples of empirical inverse CDFs, rounded to four decimals in the measurement artifact. It does not compute an exact integral over every raw cell at serving time. Scalar differences preserve their physical units. The transform is a project-defined index, not a calibrated probability.")
    equation_blocks = json.loads((DOCS / "paper/paper-content.json").read_text(encoding="utf-8"))
    blocks.extend(b for b in equation_blocks if b["type"] == "eq")
    section("19 Mathematical symbols", "E is the exact Earth AOI; P the reference AOI; T the task; H the epoch/process context; V the processing and scoring version; R the profile configuration. k indexes features and g evidence families. d is a physical distance, tau a material-difference tolerance in the same units, delta a tested resolution floor, s a feature similarity, a a within-family weight, w a planned family weight, I family eligibility, S a family score, A_obs the observed index and C evidence coverage. u is cumulative probability in the empirical quantile functions. The eligibility key includes a profile-configuration digest and a stated present-surface epoch.")
    section("20 Weights and tolerances", "Only slope and relative-elevation distributions are scored, with weight 0.50 each. Relief and roughness have zero scoring weight because of redundancy. The current exact tolerances and worked measurement values below are generated from the backend paper data.")
    blocks.append({"type": "table", "caption": "Generated Atacama south versus Jezero calculation", "header": ["Feature", "Distance", "Tolerance", "Similarity", "Weight"], "rows": [[f, str(v["d"]), str(v["tau"]), str(v["s"]), str(v["weight"])] for f,v in example["features"].items()]})
    section("21 Tolerance derivation", "Tolerances are medians of pairwise Earth-window terrain distances at each scale. The background contains 88 non-overlapping windows from four regions, taken from source tiles already acquired for known candidates. Windows are separated but not statistically independent; geography and prior candidate selection can bias calibration. Leave-one-region-out sensitivity does not constitute independent blind validation. No expert-derived boundary or measurement uncertainty is claimed for tau.")
    section("22 Resolution floor", "For each feature and reference, the floor combines the largest tested 2 km north/south/east/west reference-placement distance with the frozen Earth DEM-product difference in quadrature. A feature must satisfy tau >= 3 delta. The floor affects eligibility and interpretation; it does not subtract a distance or boost a score. Candidate differences below the floor are not resolved by the tested data and scenarios.")
    section("23 Ties and ranking", "Scenario ranges include candidate placement, reference placement, DEM choice, scale, tolerance and weight changes. Overlapping ranges are grouped; competition ranking gives group members the same position. Only the terrain profile ranks, and only within one reference/profile/configuration/eligibility identity. Ties express unresolved ordering under tested scenarios, not equal terrain or a confidence interval.")
    section("24 Evidence coverage and task gates", "Coverage is the fraction of the planned family weight that has compatible evidence. It is neither pixel coverage nor confidence. Terrain analogy can reach coverage 1 while excluding all non-terrain questions. Balanced science requires geology; rover mobility requires physical field suitability; biosignature fieldwork requires geochemical and preservation evidence; base field testing requires thermal and field evidence. Failed critical gates now produce a null overall API/export index and no scenario index. Measured family details remain visible.")
    section("25 Worked real calculation", f"The generated full-precision Atacama-south/Jezero result is {example['observed_index_full']}; the API and display use {example['observed_index_api']:.2f}. The independent reference arithmetic agrees. Recombining rounded display similarities can differ slightly. The all-cell Wasserstein check differs from the 500-quantile approximation by less than 0.1 percent in this example; this is an approximation check, not predictive accuracy.")
    section("26 Reliability and discrimination", "Against Jezero, the recorded background share at index >= 90 is " + str(paper["background_jezero"]["share_at_or_above"]["90"]) + ". High scores are common among smooth low-relief terrain. Distribution comparisons ignore the spatial arrangement of channels, ridges and hazards; a gentle synthetic control can score highly. Synthetic controls belong to method diagnostics, never production candidate evidence. No independently labelled accuracy percentage is available.")
    section("27 Sensitivity testing", "The committed evaluation contains AOI/reference translations, alternative DEMs, 60/120/240 m grids, leave-one-feature-out comparisons, tolerance and weight variations, background score distributions and leave-one-region-out calibration. The release reproduction recomputes every registered primary-grid scored quantile from local rasters. Alternative DEM scenario coverage is incomplete for Meteor Crater after a recorded provider rate limit. Expert-labelled positives, negatives and process-specific validation remain future work.")
    section("28 Security controls", "Catalog IDs constrain file access. Source hosts are allowlisted; acquisition strips credentials on cross-host redirects, bounds downloads and extraction, and uses timeouts. API bodies are capped at 32768 bytes even without Content-Length and have a 15 second receive deadline. Explore has queue and rate limits. Responses sanitize validation and server errors; production disables interactive API documentation. The tracked-file credential scan and dependency audits are repeatable, but cannot prove the absence of vulnerabilities. A reverse proxy must enforce deployment-wide rate and resource limits.")
    section("29 API reference", "Current comparison endpoints are GET /api/v3/compare, /api/v3/result, /api/v3/references, /api/v3/profiles, /api/v3/method, /api/v3/data-roles, /api/v3/sites/{site_id}/explorer and /api/v3/source-registry. Comparison query parameters are reference and profile; result also requires site. Validation failures return structured errors. The complete generated OpenAPI inventory is docs/api-reference.json. Historical endpoints carry their historical method versions and should not be mixed with v3 rankings.")
    section("30 Repository structure", "frontend/app contains pages and components; frontend/lib the typed client and response types; frontend/e2e browser tests. backend/app/data holds versioned catalog and method configuration, models schemas, services scientific logic, routers API endpoints and scripts repeatable operations. backend/data/aoi stores exact registered windows; manifests source provenance; processed measurements, imagery, evaluation and evidence. Raw/interim/cache/job storage is ignored. docs/paper contains generated methods and worked results.")
    section("31 Local setup", "Create a fresh Python environment rather than copying a virtual environment between machines. Python 3.12 or 3.13 and Node 20 or newer are documented prerequisites. This review used the working ignored .venv-local environment; the copied .venv-geo pointed to a different user's missing interpreter.")
    code("cd backend\npython -m venv .venv-local\n.venv-local/Scripts/python.exe -m pip install -r requirements-dev.txt\n.venv-local/Scripts/python.exe -m uvicorn app.main:app --host 127.0.0.1 --port 8000\n# separate terminal\ncd frontend\nnpm ci\nnpm run dev")
    section("32 Environment variables", "APP_ENV controls production API documentation. CORS_ORIGINS lists explicit browser origins. NEXT_PUBLIC_API_BASE_URL points the browser at the backend; NEXT_PUBLIC_BUILD_IDENTIFIER helps detect stale builds. ALTERECHO_PYTHON selects the interpreter used by Playwright. EARTHDATA_TOKEN or EARTHDATA_USERNAME and EARTHDATA_PASSWORD are backend-only credentials read from environment or ignored local .env. Never put credentials in NEXT_PUBLIC variables, reports, signed-URL manifests or tracked configuration.")
    section("33 Data acquisition", "Retain verified existing products. SRTM acquisition requires Earthdata credentials only for uncached protected products; do not fabricate a replacement if access fails. Mars CTX uses official STAC discovery and controlled window reads. Lunar LOLA processing follows its archived label and conversion script. Preserve raw products separately from local crops. Detailed source-specific commands and known gaps are in DATA_ACQUISITION_GUIDE.md.")
    code("cd backend\npython -m app.scripts.acquire_dataset --source-id earth-atacama-south-srtmgl1\npython -m app.scripts.register_mars_references\npython -m app.scripts.register_lunar_reference")
    section("34 Reproduction commands", "The first two commands below inspect and reproduce existing measurements without replacing scientific artifacts. Calibration and reference regeneration commands are documented separately because they write versioned outputs; review their diff before accepting a new release.")
    code("cd backend\npython -m app.scripts.audit_sources --write\npython -m app.scripts.reproduce_release\npython -m app.scripts.build_methods_paper\npython -m app.scripts.build_system_guide")
    section("35 Test commands", "Tests distinguish arithmetic, data integrity, API behavior, browser workflows and external-provider availability. A passing suite does not independently validate terrain science. The release handoff records actual results rather than a permanent claim that tests always pass.")
    code("cd backend\npython -m pytest -q\npython -m app.scripts.validate_catalog_integrity\npython -m app.scripts.release_security\npython -m pip_audit\n# PowerShell live provider checks\n$env:ALTERECHO_LIVE='1'; python -m pytest tests/test_live_providers.py -q\ncd ../frontend\nnpm run lint\nnpx tsc --noEmit\nnpm run build\n$env:ALTERECHO_PYTHON='.venv-local\\Scripts\\python.exe'\nnpm run test:e2e\nnpm audit")
    section("36 Deployment", "No deployment is performed by this release review. Serve the API behind HTTPS and a reverse proxy with explicit allowed origins, request limits and operational monitoring. Serve the production Next.js build, mount the approved small processed artifacts and isolate optional acquisition jobs. Set APP_ENV=production, verify the configured browser/API origins, then run smoke tests against the actual deployment. No user accounts are needed for the current public atlas.")
    section("37 Attribution and licences", "SRTM, NASADEM and mission products retain NASA/JPL/PDS attribution; controlled USGS CTX products cite DOI 10.5066/P9JKVWR3 and their CC0 terms. Sentinel imagery contains modified Copernicus Sentinel data. WorldCover v200 is attributed under CC-BY-4.0. Copernicus GLO-30 attribution includes DLR, Airbus and EU/ESA. OpenStreetMap/OpenFreeMap supply display basemap context. Exact terms and product links are in the source registry; permission to use a data product is separate from land access.")
    section("38 Current limitations", "The prototype has traceable terrain results but lacks independent scientific validation. Low-relief saturation, calibration geography, distribution-only descriptors, stereo noise, imperfect land-cover masks, unknown effective resolution and incomplete product-label metadata limit interpretation. Thermal constructs have mismatched spatial and temporal support; minerals, resources and field constraints remain diagnostic or unavailable. Original Atacama is excluded; lunar distances do not constitute a scored analogue result.")
    section("39 Future scientific validation", "Obtain an independently labelled evaluation set with accepted process-specific analogues, partial analogues, same-region mismatches and separated negative controls. Preregister AOI and tolerance selection, then assess discrimination, false positives and geographic transfer without calibration leakage. Add a spatial descriptor only with a new method version and redundancy analysis. Thermal or mineral families require compatible physical quantities, quality flags, support and reproducible specialist processing on both bodies.")
    section("40 References", "Primary scientific references are the exact products and papers in the registry and generated methods paper. Useful official entry points include NASA CMR (https://cmr.earthdata.nasa.gov/search/site/docs/search/api.html), USGS CTX DTM documentation (https://stac.astrogeology.usgs.gov/docs/data/mars/ctxdtms/), NASA PDS LOLA (https://pds-geosciences.wustl.edu/missions/lro/lola.htm) and the Microsoft Planetary Computer STAC API (https://planetarycomputer.microsoft.com/api/stac/v1). NASA Analog Explorer supplies research context, not numerical proof of similarity.")
    md = []
    for b in blocks:
        if b["type"] in {"title", "h1"}: md.append(("# " if b["type"] == "title" else "## ") + b["text"])
        elif b["type"] == "p": md.append(b["text"])
        elif b["type"] == "code": md.append("```text\n" + b["text"] + "\n```")
        elif b["type"] == "eq": md.append("$$\n" + b["latex"] + "\n$$")
        elif b["type"] == "table": md.append("| " + " | ".join(b["header"]) + " |\n| " + " | ".join(["---"]*len(b["header"])) + " |\n" + "\n".join("| " + " | ".join(r) + " |" for r in b["rows"]))
        elif b["type"] == "diagram":
            mermaid = "flowchart LR\n" + "\n".join(f'  n{i}["{x}"]' for i,x in enumerate(b["nodes"])) + "\n  " + " --> ".join(f"n{i}" for i in range(len(b["nodes"])))
            (DOCS / f"{b['text']}.mmd").write_text(mermaid + "\n", encoding="utf-8")
            md.append("```mermaid\n" + mermaid + "\n```")
    calc = 'flowchart LR\n E[Earth quantiles] --> D[Physical W1 distance]\n P[Reference quantiles] --> D\n D --> G{Comparability and critical gates}\n G -->|pass| S[Feature transform and family weights]\n G -->|fail| N[Null index and explicit missing evidence]\n S --> O[Index and evidence coverage]\n'
    (DOCS / "calculation-flow.mmd").write_text(calc, encoding="utf-8")
    (DOCS / "ALTERECHO_SYSTEM_AND_RESEARCH_GUIDE.md").write_text("\n\n".join(md) + "\n", encoding="utf-8", newline="\n")
    (DOCS / "system-guide-content.json").write_text(json.dumps(blocks, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    (DOCS / "api-reference.json").write_text(json.dumps(app.openapi(), indent=2) + "\n", encoding="utf-8", newline="\n")
    inventory = ["# Data source registry", "Generated from source-registry-v1. Collection rows are candidate metadata; exact product rows record local-byte verification. Unknown fields remain null. API: `/api/v3/source-registry`. Full checksums and raster metadata: `backend/data/manifests/acquisition-v1/source-registry.json`.", "| Dataset or product | Role | Status | Source |\n|---|---|---|---|"]
    inventory.extend(f"| {r['dataset_id']} | {r['role']} | {r['status']} | [{r['provider']}]({r['official_landing_page']}) |" for r in registry["records"])
    inventory.append("## Exact local terrain input checksums\n")
    inventory.extend(f"- `{r['raw_filename']}`: `{r['sha256']}` ({r['byte_size']} bytes)" for r in registry["records"] if r.get("raw_filename"))
    (DOCS / "DATA_SOURCE_REGISTRY.md").write_text("\n\n".join(inventory), encoding="utf-8", newline="\n")
    print(f"Generated master guide with {len(blocks)} content blocks and an exact source inventory")


if __name__ == "__main__":
    build()
